programs.haiku:
"""Passive-voice auxiliary detector for one MLP component (layers.15 down_proj, #2689).

What it does: it fires on forms of "be" (is, are, was, were, be, been, being) when the
form is an auxiliary that a past participle is likely to follow, i.e. the start of a
passive ("...was signed", "...can be used", "...have been described"). It is strongest
after a noun phrase or a modal/"have" ("can be", "has been", "The Moscow Armistice was"),
weaker after a pronoun ("it is", "this is") and weakest after "there" ("there is").
It also fires moderately on an adverb sitting between the auxiliary and its participle
("is typically used", "was not known", "have also been"). Everywhere else it sits near
its resting value.

Only the prefix is read: the rule looks at the token and the one before it, in the same
document.
"""

READS = ()

BE_FORMS = {"is", "are", "was", "were", "be", "been", "being"}
# Auxiliaries that take a passive participle straight after them.
MODAL_OR_HAVE = {"can", "could", "will", "would", "should", "may", "might", "must",
                 "have", "has", "had"}
# Words that often start a non-passive "be" clause: "there is", "it is", "this is".
WEAK_LEAD = {"there", "here", "it", "this", "what", "how", "i", "you", "we", "they"}
# Adverbs that can sit between "be" and a participle.
ADVERBS = {"not", "also", "often", "usually", "originally", "never", "sometimes", "then",
           "generally", "commonly", "previously", "initially", "primarily", "widely",
           "thus", "therefore", "later", "first", "always", "still", "already", "only",
           "now", "just", "frequently", "traditionally", "mostly", "typically"}

REST = -0.07  # typical value of every other token


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in BE_FORMS:
        if before in WEAK_LEAD:
            value = 1.0
        elif before in MODAL_OR_HAVE:
            value = 5.0
        else:
            value = 3.8
    elif before in BE_FORMS and word in ADVERBS:
        value = 3.0
    else:
        value = REST
    return carry, value

"""Layer 15, MLP hidden unit 2690. The component reads this unit almost alone (weight 0.83
of its 1.05 input norm), so its activation tracks the unit's value (correlation 0.78).
The program predicts that unit's activity from the text so far.

Plain-language summary of what the unit responds to: it is mostly quiet, and its
clearest responses come inside coordinated phrases, "X and Y", "X or Y", "both X and Y":
  * up: a plural noun that completes a coordination ("...Medicare and [Medicaid]",
    "...rope and [knots]", "...shares, likes and [...]");
  * down: an auxiliary verb (are, were, is, ...) after a coordinated subject
    ("the vehicle and the police [were]"), and the words both / either / neither.
Everywhere else it sits near a small negative baseline.

These word rules explain only a small share of its variance: most of the unit's
spread comes from context the rules do not capture, so the program is a sketch.
"""

READS = ()

CONJUNCTIONS = {"and", "or", "nor"}
BOTH_WORDS = {"both", "either", "neither"}
AUXILIARIES = {
    "are", "were", "is", "was", "be", "been", "should", "can",
    "will", "would", "must", "may", "have", "has", "had",
}
SENTENCE_STOPS = {".", ";", "!", "?"}
BASELINE = -0.04
PLURAL_AFTER_CONJUNCTION = 1.0
AUXILIARY_AFTER_COORDINATION = -0.35
BOTH_WORD_NEARBY = -0.3


def _is_plural_noun(word):
    return word.isalpha() and len(word) > 3 and word.endswith("s")


def _recent_words(prefix, limit):
    """Lowercase words before the current token, newest first, within its document and sentence."""
    words = []
    doc = prefix.document_ids[-1]
    for i in range(len(prefix.token_ids) - 2, -1, -1):
        raw = prefix.token_strings[i]
        word = raw.strip().lower()
        if prefix.document_ids[i] != doc or word in SENTENCE_STOPS or "\n" in raw:
            break
        words.append(word)
        if len(words) == limit:
            break
    return words


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    recent = _recent_words(prefix, 8)
    if recent and recent[0] in CONJUNCTIONS and _is_plural_noun(word):
        return carry, PLURAL_AFTER_CONJUNCTION
    coordinated = any(w in CONJUNCTIONS for w in recent)
    if word in AUXILIARIES and coordinated:
        return carry, AUXILIARY_AFTER_COORDINATION
    if any(w in BOTH_WORDS for w in recent[:5]):
        return carry, BOTH_WORD_NEARBY
    return carry, BASELINE

"""Layer 15 MLP hidden unit 2694 (component down_proj:2694), as a word-class rule.

What it responds to: words that name an established result or a stated piece of
knowledge. Strongest on named mathematical results ("theorem", "Lemma", "Proposition"),
moderate on words for facts, laws, principles, observations, statements and conjectures,
and weakly on words like "interesting", "surprising" and "known". It is mildly negative on
logical connectives that open a conclusion ("therefore", "thus", "hence"). "In fact" and
"in principle" are idioms, not claims, so they are switched off.

This is a lexical approximation only. Looking up the word alone explains a few per cent of
the variance; most of the activation depends on context that this rule does not model.
"""

READS = ()

NAMED_RESULT = {"theorem": 10.0, "lemma": 10.0, "proposition": 9.0}
CLAIM_WORD = {
    "fact": 2.0, "facts": 3.0, "law": 2.0, "principle": 3.0, "observation": 3.0,
    "statement": 2.0, "assertion": 2.0, "conclusion": 2.0, "conjecture": 4.0,
    "proof": 1.0, "prove": 1.0, "truth": 1.0, "note": 2.0, "recall": 2.0,
    "interesting": 2.0, "surprising": 3.5, "hypothesis": 1.5, "known": 1.0,
}
CONNECTIVE = {
    "therefore": -0.6, "thus": -0.6, "hence": -0.6,
    "consequently": -0.8, "nevertheless": -0.6, "actually": -0.4,
}
IDIOM_PREVIOUS = {"in"}  # "in fact", "in principle", "in law"
IDIOM_WORDS = {"fact", "facts", "principle", "law"}
OTHER = -0.03  # the dataset mean for every other token


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position > 0 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        word_prev = ""
    else:
        word_prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    table = {**NAMED_RESULT, **CLAIM_WORD, **CONNECTIVE}
    if word_prev in IDIOM_PREVIOUS and word in IDIOM_WORDS:
        return carry, 0.0
    return carry, table.get(word, OTHER)

"""Coordinating conjunctions: "and" / "or" and their equivalents in other languages.

This component goes negative on the word that joins two items or phrases, as in
"cats and dogs", "tea or coffee", "Russell Lee and Universal Studios". Its size depends
on the word and on what comes just before it:
- a joining and/or (and, or, und, oder, ou, или, 和, 或, や, ...): about -2.7;
- a looser joiner (et, nor, ve, y, e, &, ja, 与, 并, ...): about -1.4;
- a sentence-initial And/Or, uppercase AND/OR, or the Japanese comma 、: about -1.0;
- directly after a comma (", and" joins clauses more loosely), the value is halved.
Every other token predicts 0. Those tokens carry only small, unpatterned values, and
the conjunctions explain about a quarter of the component's variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

STRONG = {
    " and", " or", "/or", " und", " oder", " og", " och", " dan", " ou", " или", " и",
    " và", " و", " oraz", " eller", " sau", " şi", " și", " ili", " veya", " atau",
    "和", "或", "或者", "及", "や", "或は", "又は", "และ", "หรือ",
}
WEAK = {" et", " nor", " ve", " ja", " y", " e", " &", " hay", " ó", " és", "与", "并", "以及", "と", "與", "αι", "・"}
MILD = {" And", " Or", "And", "Or", "and", " AND", " OR", "、"}
COMMA = {",", "，", "、", " ,"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok in STRONG:
        value = -2.7
    elif tok in WEAK:
        value = -1.4
    elif tok in MILD:
        value = -1.0
    else:
        return carry, 0.0
    if prev in COMMA:
        value *= 0.5
    return carry, value

"""A line break that cuts a sentence in two.

Component p-82af68dd@100000/layers.15.mlp.down_proj:2714 is a "mid-sentence line break"
detector. It is silent on almost every token. It fires on a token that contains a line
break (a newline, a carriage return, or a literal backslash-n), and only when the text
just before that break is not the end of a sentence:

- a break right after a word that demands a continuation ("the", "of", "to", "and", "for",
  "with", "in", ...) is the strongest case: the sentence obviously goes on at the next line.
  It is strongest when the broken line is about the width of a hard-wrapped paragraph
  (40 to 90 characters);
- a break after a weaker function word ("a", "is", "that", "as", ...) is moderately positive,
  and after a pronoun or adverb that can end a sentence ("it", "this", "so", ...) barely so;
- a break after a chat role or tool tag ("user", "<tool_response>", ...) is positive;
- a break after another word or a digit is weakly positive;
- a break after sentence-final punctuation (". ! ? : ;") is about zero.

Every token without a line break is zero.
"""

STRONG = frozenset(
    "the of to and or for with from by in on at into than not nor but".split()
)
MEDIUM = frozenset(
    "a an is are was were be been that as if which its their his her our my your".split()
)
WEAK = frozenset("it this so then you no".split())
TOOL_TAGS = ("<tool_call>", "<tool_response>")
BREAKS = ("\n", "\r", "\\n")
SENTENCE_END = (".", "!", "?", ":", ";")
WRAP_LOW, WRAP_HIGH = 40, 90


def line_length(token_strings):
    """Characters since the last line break, before the newest token."""
    n = 0
    for text in reversed(token_strings[:-1]):
        if any(b in text for b in BREAKS):
            break
        n += len(text)
    return n


READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not any(b in token for b in BREAKS):
        return None, 0.0
    # The text before the break: the token's own characters, else the previous token's.
    before = token.split("\n")[0].split("\r")[0].split("\\n")[0]
    if not before.strip() and prefix.position > 0:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            before = prefix.token_strings[-2]
    if before.rstrip().endswith(SENTENCE_END):
        return None, 0.0
    word = before.strip().lower()
    if word in STRONG:
        n = line_length(prefix.token_strings)
        return None, (6.0 if WRAP_LOW <= n <= WRAP_HIGH else 2.0)
    if word in MEDIUM:
        return None, 2.5
    if word in WEAK:
        return None, 0.5
    if before.strip() in TOOL_TAGS:
        return None, 5.0
    if before.strip().startswith("<") or word in ("user", "assistant"):
        return None, 1.5
    return None, 0.5

"""Predicts layers.15.mlp.down_proj component 2718 from the newest token alone.

This component is a weak, diffuse signal. Its size is set mostly by context that no word list
captures, and its large spikes, which carry most of its variance, are not predicted here. What
the newest token does set, on average, measured on training text:

- the word "or" is high (about +0.8), and so are closing quotation and bracket marks
  (about +0.3) and commas (about +0.2);
- nouns, rarer words and Chinese characters sit a little above zero;
- first- and second-person and possessive pronouns ("I", "you", "my", "his", "her"),
  the demonstratives "this" and "that", and a few adverbs ("just", "well", "though", "too")
  sit below zero (about -0.2 to -0.5);
- spaces and common function words sit near zero.

Each kind is predicted at its average. On eval rows the predictions explain about a third of
a percent of the activation's variance (Pearson r about 0.07), so this is a description of
the component's typical level, not of when it spikes.
"""

import regex
import wordfreq
import wordnet

READS = ()

LEVEL = {" or": 0.8, ",": 0.2, "，": 0.25}
CLOSING = {'"', "”", "’", "»", "」", ")", ',"', ',”', '."', '.”', '!"', '?”', '?"'}
PRONOUNS = {"i", "you", "my", "his", "her"}
DEMONSTRATIVES = {"this", "that"}
ADVERBS = {"just", "well", "though", "too"}


def guess(token):
    """The average activation of the token's kind."""
    if token in LEVEL:
        return LEVEL[token]
    word = token.strip()
    if not word:
        return 0.0
    if word in CLOSING or token in CLOSING:
        return 0.3
    if regex.fullmatch(r"\p{Han}+", word):
        return 0.09
    if regex.fullmatch(r"\p{N}+", word):
        return 0.02
    if regex.fullmatch(r"\p{L}+", word):
        low = word.lower()
        if low == "and":
            return 0.13
        if low in PRONOUNS or low in DEMONSTRATIVES:
            return -0.2
        if low in ADVERBS:
            return -0.4
        if "noun" in wordnet.parts_of_speech(low):
            return 0.16
        if wordfreq.zipf_frequency(low, "en") < 4.0:
            return 0.12
        return 0.03
    return 0.09


def step(carry, prefix, upstream):
    """The average activation of the newest token's kind; nothing is carried forward."""
    return carry, guess(prefix.token_strings[-1])

"""Predicts layers.15.mlp.down_proj component 2734 from the tokens alone.

This component is a diffuse, near-silent direction in layer 15's MLP output. Its
activation has mean about -0.05 and spread about 0.37, but no clean concept
explains it: token identity explains only about 3% of its variance, and the simple
readable features below explain about 0.3%. The program keeps the few tendencies
that were found by fitting on training rows:

  - the first token of each document (or of each packed row) sits near -0.01;
  - hedging and reasoning words (maybe, perhaps, wait, alternatively) push it up;
  - chat and reasoning markers such as <think>, </think> and <|im_end|> push it up;
  - code punctuation and source-file extensions push it down a little;
  - Han characters push it down a little; digits push it up a little;
  - all other tokens sit at its mean, about -0.047.

The program keeps no state beyond the position check and reads no other component.
"""

import re

HEDGES = {"maybe", "perhaps", "actually", "really", "wait", "alternatively", "probably", "might", "possibly"}
ANGLE_TAG = re.compile(r"\s*<[^<>\s]*>\s*")
CODE = re.compile(r"\.(py|js|ts|go|java|cpp|rs|sh)$|[_(){}\[\];=<>]")
HAN = re.compile(r"[一-鿿]")
DIGITS = re.compile(r"\s*[0-9]+")

READS = ()

MEAN = -0.047
DOC_START = -0.011


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    starts_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_document:
        return carry, DOC_START
    value = MEAN
    if text.strip().lower() in HEDGES:
        value += 0.20
    if ANGLE_TAG.fullmatch(text):
        value += 0.18
    if CODE.search(text):
        value -= 0.03
    if HAN.search(text):
        value -= 0.02
    if DIGITS.fullmatch(text):
        value += 0.03
    if text.strip() == "":
        value -= 0.01
    return carry, value

"""Layer 15 MLP down_proj, component 2747: a weak, mostly context-driven feature.

What it does: its activation depends mostly on the kind of token it sits on.
Infix operators and symbols (+, -, =, ==, ->, ::, |) and the word "with" push it
clearly negative. Other connecting words (and, or, to, as, is, from) and the
separators , : ; ! are mildly negative. Newlines, determiners and pronouns (the,
of, that, it, you), digits and ordinary words are mildly positive; a period is
about neutral. The program predicts each class's average activation. Token kind
explains only a small share of the variance; the rest depends on context that
this program does not model.
"""

import unicodedata

READS = ()

OPERATORS = {
    "+", "-", "*", "/", "=", "==", "!=", "+=", "-=", "->", "=>", "::", "|", "&",
    "<", ">", "%", "^", "—", "–",
}
SEPARATORS = {",", ":", ";", "!", "?"}
CONNECTIVES = {
    "and", "or", "by", "to", "as", "is", "be", "are", "from", "but", "for", "in",
    "on", "at", "if", "than", "using", "via",
}
DETERMINERS = {
    "the", "a", "an", "this", "that", "it", "of", "you", "they", "he", "she", "we", "i",
}

# Average activation per class, fit on 4096 training rows (about 2M tokens).
MEAN = {
    "space": -0.02,
    "newline": 0.17,
    "period": -0.01,
    "digit": 0.09,
    "with": -1.25,
    "operator": -0.88,
    "separator": -0.19,
    "connective": -0.16,
    "determiner": 0.16,
    "other_punct": -0.17,
    "word": 0.09,
    "mixed": 0.0,
}


def kind_of(token: str) -> str:
    text = token.strip().lower()
    if not text:
        return "newline" if "\n" in token else "space"
    if text == ".":
        return "period"
    if text.isdigit():
        return "digit"
    if text == "with":
        return "with"
    if text in OPERATORS:
        return "operator"
    if text in SEPARATORS:
        return "separator"
    if text in CONNECTIVES:
        return "connective"
    if text in DETERMINERS:
        return "determiner"
    if all(unicodedata.category(c)[0] in "PS" for c in text):
        return "other_punct"
    if text.isalpha():
        return "word"
    return "mixed"


def step(carry, prefix, upstream):
    # The first position of a row has almost no activation.
    if prefix.position == 0:
        return carry, 0.0
    return carry, MEAN[kind_of(prefix.token_strings[-1])]

"""Layer 15 MLP down_proj, component 2749.

What it does, in plain terms: this component writes toward "the end result is coming".
Its output direction raises the next-token odds of "finally", "eventually", "ultimately",
"final", "conclusion" and their Chinese equivalents, and lowers "immediately", "immediate",
"urgently". So its activation is largest where the text is about to say how something
ends up or when it happens: on words like "finally", "ultimately", "eventually", on
"before", "until", "till" ("...waited before leaving", "...until it was banned"), on "to"
after lead-verbs ("led up to", "lead me to"), on "but"/"then"/"thus", and on the comma
that closes an introductory time or cause phrase ("After three years of adventures, ...").
It is slightly negative on digits, code and symbols, and on "unless" and "or".

This program scores those cues with a few hand-set values and nothing else. Its fit is
weak: about 2% of the variance of held-out sampled positions. The activation is mostly
context-dependent detail that no word list captures.
"""

READS = ()

OUTCOME = {
    "finally", "eventually", "ultimately", "eventual", "ultimate", "final", "finale",
    "climax", "conclusion", "culmination", "ending", "concluding",
}
SEQUENCE = {"before", "until", "till", "reach", "reached", "reaches", "leading", "led", "leads", "lead"}
CONNECTIVE = {"but", "then", "so", "thus", "therefore", "however", "hence"}
LEAD_WORDS = {"lead", "led", "leading", "leads", "up", "from", "reach", "reached", "get", "got", "came", "come"}
NEGATIVE = {"unless", "or"}
INTRO_WORDS = {
    "after", "following", "before", "when", "once", "during", "despite", "although", "while",
    "since", "upon", "in", "for", "with", "at", "by", "on", "from", "under", "because",
}
SENTENCE_END = {".", "!", "?", "。"}


def _word(text):
    return text.strip().lower()


def _ends_sentence(text):
    return "\n" in text or _word(text) in SENTENCE_END


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids

    def same_doc(i):
        return i >= 0 and doc[i] == doc[t]

    word = _word(prefix.token_strings[t])
    prev = _word(prefix.token_strings[t - 1]) if same_doc(t - 1) else ""

    value = 0.0
    if word in OUTCOME:
        value = 2.0
    elif word in SEQUENCE:
        value = 1.7
    elif word in CONNECTIVE:
        value = 0.6
    elif word == "to":
        value = 1.5 if prev in LEAD_WORDS else 0.15
    elif word == "and":
        value = 0.35
    elif word in NEGATIVE:
        value = -0.35
    elif word.isdigit():
        value = -0.03
    elif word and all(not c.isalnum() for c in word):
        value = -0.015

    if word in {",", "，"}:
        value = 0.5 if word == "，" else 0.15
        # A comma that closes an introductory phrase: scan back to the sentence start.
        k = t - 1
        first = None
        while same_doc(k) and t - k < 25 and not _ends_sentence(prefix.token_strings[k]):
            first = k
            k -= 1
        if first is not None and _word(prefix.token_strings[first]) in INTRO_WORDS:
            value = 0.4

    return carry, float(value)

"""Claims-and-truth detector for MLP neuron 2751 of layer 15.

This component is one MLP hidden unit (neuron 2751) read out by its down-projection. The
unit is active on words about what is claimed, alleged, believed, doubted or checked for
truth: "allegations", "alleged", "denies", "believe", "claimed", "doubt", "wrong", "really",
"true", "sure". Its activation is near zero on most other tokens.

The program reads only the current token. It gives three levels: the strongest
allegation, denial and belief words get a high value, claim and truth-testing words a
medium one, and softer epistemic words (true, really, sure, though, indeed) a low one.
Everything else gets the typical resting value, about 0.04, the component's mean.
"""

READS = ()

HIGH = {
    "allegation", "allegations", "alleged", "allegedly", "allege", "alleges", "deny", "denies",
    "denied", "myth", "myths", "mistaken", "nonsense", "convinced", "believe", "believed",
    "assertions", "contention", "contends", "claiming", "suspected", "insisted", "kidding",
    "swear", "disagree", "contradictory",
}
MEDIUM = {
    "claim", "claims", "claimed", "belief", "truth", "truths", "verify", "confirm", "confirmed",
    "doubt", "doubts", "wrong", "fake", "prove", "argue", "accused", "accuse", "assert",
    "asserted", "insist", "suspect", "legend", "legends", "mistake",
}
LOW = {
    "true", "really", "sure", "though", "although", "indeed", "honestly", "truly", "actually",
    "wait", "reports", "reportedly", "but", "said", "evidence", "fact", "facts",
}
REST = 0.04
VALUES = {"high": 2.5, "medium": 1.2, "low": 0.5}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in HIGH:
        value = VALUES["high"]
    elif word in MEDIUM:
        value = VALUES["medium"]
    elif word in LOW:
        value = VALUES["low"]
    else:
        value = REST
    return carry, value
